// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        // actor must be a distinct, initially-unblacklisted account (the test contract itself is the owner)
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // 1. Move some supply out through the public airdrop so that
        //    totalRemaining != totalDistributed afterwards.
        vm.prank(actor); // fresh actor is not blacklisted, c.value (2500e18) <= totalRemaining
        c.getTokens();

        uint256 remainingAfterDrop = c.totalRemaining();

        // 2. Owner initializes balances through NETM.
        vm.prank(address(this));
        c.NETM();

        // 3. General rule: NETM() must credit the owner with the total distributed so far,
        //    i.e. the owner's balance plus the undistributed remainder the owner did NOT
        //    receive equals the whole supply from the other side:
        //    balanceOf(owner) == totalSupply() - totalRemaining().
        //    Reference: holds for every admissible actor (balance = totalDistributed = supply - remaining).
        //    Mutant: balance = totalRemaining != supply - remaining once the airdrop shifted remaining.
        assertTrue(c.balanceOf(address(this)) == c.totalSupply() - remainingAfterDrop);
    }
}
